from PIL import Image
import numpy as np
import base64

def chunks(lst, n):
    """Yield successive n-sized chunks from lst."""
    for i in range(0, len(lst), n):
        yield lst[i:i + n]

# Load and XOR images
img1 = np.array(Image.open('/home/ctfplayer/ctf_files/image1.png'))
img2 = np.array(Image.open('/home/ctfplayer/ctf_files/image2.png'))
xored = np.bitwise_xor(img1, img2)

# Convert to uint8 type
xored = xored.astype(np.uint8)

# Create binary string from middle rows where text likely is
middle_start = xored.shape[0] // 2 - 20
middle_end = xored.shape[0] // 2 + 20

print("Image shapes:")
print("Image 1:", img1.shape)
print("Image 2:", img2.shape)
print("XORed:", xored.shape)

print("\nAnalyzing middle section rows...")
for row in range(middle_start, middle_end):
    # Convert row to bytes directly
    row_bytes = bytes(xored[row].flatten())

    # Try direct ASCII
    try:
        ascii_str = row_bytes.decode('ascii')
        if 'flag' in ascii_str.lower():
            print(f"Found potential flag pattern in row {row}:", ascii_str)
    except:
        pass

    # Try base64 decoding
    try:
        decoded = base64.b64decode(row_bytes)
        if b'flag' in decoded.lower():
            print(f"Found potential base64 flag in row {row}:", decoded)
    except:
        pass

print("\nSaving visualization...")
# Save middle section enhanced
middle_section = xored[middle_start:middle_end, :]
Image.fromarray(middle_section).save('middle_section.png')

# Analyze RGB channels separately
print("\nAnalyzing RGB channels separately...")
for channel in range(3):
    channel_xored = xored[:,:,channel]
    # Look for patterns in the middle section
    middle_data = channel_xored[middle_start:middle_end, :]
    for row_idx, row in enumerate(middle_data):
        try:
            row_bytes = bytes(row)
            # Try direct string conversion
            try:
                str_data = row_bytes.decode('ascii')
                if 'flag' in str_data.lower():
                    print(f"Found flag in channel {channel}, row {row_idx} (ASCII):", str_data)
            except:
                pass

            # Try base64
            try:
                decoded = base64.b64decode(row_bytes)
                if b'flag' in decoded.lower():
                    print(f"Found flag in channel {channel}, row {row_idx} (Base64):", decoded)
            except:
                pass
        except:
            pass

# Additional analysis: try different row combinations
print("\nTrying different row combinations...")
for i in range(middle_start, middle_end-1):
    try:
        combined_row = bytes(xored[i]) + bytes(xored[i+1])
        try:
            decoded = base64.b64decode(combined_row)
            if b'flag' in decoded.lower():
                print(f"Found flag in combined rows {i},{i+1}:", decoded)
        except:
            pass
    except:
        pass
